import data from "@/content/chains/oracles.json";

/**
 * Price feeds per network (M162), generated by scripts/gen-oracles.mjs
 * from Chainlink's feed directory and committed; nothing is fetched at
 * runtime. The Robinhood testnet has no directory (`absent`), so a
 * dependency check there reads mainnet only or a recorded mock. The
 * Robinhood Chain docs name Chainlink as the chain's oracle; Pyth and
 * RedStone are added here the day either confirms a deployment.
 */
export const ORACLE_NETWORKS = ["robinhood_mainnet", "robinhood_testnet", "arbitrum_one", "arbitrum_sepolia"] as const;
export type OracleNetwork = (typeof ORACLE_NETWORKS)[number];

export type OracleProvider = "chainlink" | "mock";
export type OracleAssetClass = "crypto" | "equity" | "fx" | "commodity" | "other";

export interface OracleFeed {
  /** The base asset as a ticker, GOOGL for the tokenized equity feed. */
  asset: string;
  quote: string;
  /** The feed's own name, "USDG / USD". */
  pair: string;
  provider: OracleProvider;
  /** The proxy address, checksummed as the directory gives it. */
  address: string;
  kind: "price" | "exchange_rate";
  assetClass: OracleAssetClass;
  /** Seconds between forced updates, null when the directory gives none. */
  heartbeat: number | null;
  decimals: number | null;
  /** The directory page the row came from. */
  source: string;
}

interface OracleFile {
  checkedOn: string;
  directory: string;
  networks: Record<OracleNetwork, { feeds: OracleFeed[]; absent: boolean }>;
}

const file = data as OracleFile;

/** The day the directory was read. */
export const ORACLES_CHECKED_ON: string = file.checkedOn;

export const ORACLE_FEEDS: Record<OracleNetwork, readonly OracleFeed[]> = {
  robinhood_mainnet: file.networks.robinhood_mainnet.feeds,
  robinhood_testnet: file.networks.robinhood_testnet.feeds,
  arbitrum_one: file.networks.arbitrum_one.feeds,
  arbitrum_sepolia: file.networks.arbitrum_sepolia.feeds,
};

/** True when the provider publishes no directory for the network at all. */
export const ORACLE_DIRECTORY_ABSENT: Record<OracleNetwork, boolean> = {
  robinhood_mainnet: file.networks.robinhood_mainnet.absent,
  robinhood_testnet: file.networks.robinhood_testnet.absent,
  arbitrum_one: file.networks.arbitrum_one.absent,
  arbitrum_sepolia: file.networks.arbitrum_sepolia.absent,
};
